int assertions = 0;
void Check(bool ok, string label) { assertions++; if (!ok) throw new Exception(label); }
(GameBridge bridge, GameItem a, GameItem b) Setup(bool owned = false) {
    FakeContext.Bridge = null;
    PlayerStore.Instance = new PlayerStore(); EmporiumEntry.Instance = new EmporiumEntry();
    StoreStation.Instance = new StoreStation(); ModHelper.Data.Clear(); ModHelper.Outside = false;
    var a = new GameItem { Id = 10, Price = 4, Owned = owned, parentInventory = EmporiumEntry.Instance.Front };
    var b = new GameItem { Id = 11, Price = 5, Owned = owned, parentInventory = EmporiumEntry.Instance.Front };
    EmporiumEntry.Instance.Items.AddRange(new[] { a,b });
    var bridge = new GameBridge(); FakeContext.Bridge = bridge; bridge.Snapshot(); return (bridge,a,b);
}
JObject Offer(bool selling = false, int a = 3, int b = 4, int total = 7) => new JObject {
    ["action"] = "propose_bundle", ["direction"] = selling ? "player_sells" : "player_buys", ["total"] = total,
    ["items"] = new JArray(new JObject { ["item_id"] = 10, ["price"] = a }, new JObject { ["item_id"] = 11, ["price"] = b }) };
JObject Adjust(int expected, int delta) => new JObject { ["action"] = "adjust_budget", ["expected_budget"] = expected, ["delta"] = delta };
JObject Leave() => new JObject { ["action"] = "leave", ["speech"] = "I'm leaving." };
void Buyer(GameBridge b, int amount) { b.Client.clientIntent = StoreClient.ClientIntent.BUY; b.Client.useClientBudget = true; b.Client.Budget = amount; b.Snapshot(); }
JObject Trade(GameBridge bridge, List<GameItem> items, bool selling = false) {
    if (!bridge.Bundle.Begin(items, selling)) return GameBridge.Error("rejected");
    bool failed = false;
    try { foreach (var item in items.AsEnumerable().Reverse()) { if(selling) PlayerStore.Instance.SellItem(item); else PlayerStore.Instance.BuyItem(item); } }
    catch { failed = true; }
    return bridge.Bundle.Finish(failed);
}
